#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&]() -> double {
        return chrono::duration<double>(chrono::steady_clock::now()-startTime).count();
    };

    int N;
    cin >> N;
    vector<double> cx(N), cy(N);
    for(int i=0;i<N;i++) cin >> cx[i] >> cy[i];

    vector<bool> is_prime(N, false);
    {
        vector<bool> sieve(max(N,2), true);
        sieve[0]=false; sieve[1]=false;
        for(int i=2;(long long)i*i<N;i++)
            if(sieve[i])
                for(int j=i*i;j<N;j+=i) sieve[j]=false;
        for(int i=0;i<N;i++) is_prime[i]=sieve[i];
    }

    auto ddist = [&](int a, int b) -> double {
        double dx=cx[a]-cx[b], dy=cy[a]-cy[b];
        return sqrt(dx*dx+dy*dy);
    };

    auto getmult = [&](int step, int src) -> double {
        return (step%10==0 && !is_prime[src]) ? 1.1 : 1.0;
    };

    auto tourCost = [&](const vector<int>& t) -> double {
        double cost=0;
        for(int s=1;s<=N;s++){
            cost += ddist(t[s-1],t[s]) * getmult(s, t[s-1]);
        }
        return cost;
    };

    // Grid-based nearest neighbor
    double minx=1e18, maxx=-1e18, miny=1e18, maxy=-1e18;
    for(int i=0;i<N;i++){
        minx=min(minx,cx[i]); maxx=max(maxx,cx[i]);
        miny=min(miny,cy[i]); maxy=max(maxy,cy[i]);
    }

    int gridSize = max(1, (int)sqrt((double)N / 4.0));
    double cellW = (maxx-minx)/gridSize + 1e-9;
    double cellH = (maxy-miny)/gridSize + 1e-9;
    if(cellW < 1e-12) cellW = 1.0;
    if(cellH < 1e-12) cellH = 1.0;

    auto getCellXY = [&](double x, double y) -> pair<int,int> {
        int gx = min(gridSize-1, max(0,(int)((x-minx)/cellW)));
        int gy = min(gridSize-1, max(0,(int)((y-miny)/cellH)));
        return {gx, gy};
    };

    vector<vector<int>> grid(gridSize*gridSize);
    for(int i=0;i<N;i++){
        auto [gx,gy]=getCellXY(cx[i],cy[i]);
        grid[gy*gridSize+gx].push_back(i);
    }

    auto buildNNTour = [&](int start) -> vector<int> {
        // Rebuild grid
        vector<vector<int>> g(gridSize*gridSize);
        for(int i=0;i<N;i++){
            auto [gx,gy]=getCellXY(cx[i],cy[i]);
            g[gy*gridSize+gx].push_back(i);
        }

        vector<bool> visited(N, false);
        vector<int> t(N+1);
        t[0]=start;
        visited[start]=true;
        {
            auto [gx,gy]=getCellXY(cx[start],cy[start]);
            auto &v=g[gy*gridSize+gx];
            v.erase(find(v.begin(),v.end(),start));
        }

        for(int step=1;step<N;step++){
            int last=t[step-1];
            auto [gx0,gy0]=getCellXY(cx[last],cy[last]);
            int best=-1; double bestD=1e30;

            for(int rad=0;rad<=2*gridSize;rad++){
                if(best!=-1){
                    double minPoss = max(0.0, (double)(rad-1)) * min(cellW,cellH);
                    if(minPoss > bestD*1.5) break;
                }
                int found=0;
                for(int dx=-rad;dx<=rad;dx++){
                    for(int dy=-rad;dy<=rad;dy++){
                        if(abs(dx)!=rad && abs(dy)!=rad) continue;
                        int gx=gx0+dx, gy=gy0+dy;
                        if(gx<0||gx>=gridSize||gy<0||gy>=gridSize) continue;
                        auto &v=g[gy*gridSize+gx];
                        for(int id : v){
                            if(!visited[id]){
                                double d=ddist(last,id);
                                if(d<bestD){bestD=d;best=id;}
                                found++;
                            }
                        }
                    }
                }
                if(best!=-1 && rad>0) break;
            }
            t[step]=best;
            visited[best]=true;
            {
                auto [gx,gy]=getCellXY(cx[best],cy[best]);
                auto &v=g[gy*gridSize+gx];
                v.erase(find(v.begin(),v.end(),best));
            }
        }
        t[N]=start;

        // Rotate to start at 0
        if(start!=0){
            int zp=-1;
            for(int i=0;i<N;i++) if(t[i]==0){zp=i;break;}
            vector<int> rt(N+1);
            for(int i=0;i<N;i++) rt[i]=t[(zp+i)%N];
            rt[N]=0;
            return rt;
        }
        return t;
    };

    vector<int> tour = buildNNTour(0);
    double curCost = tourCost(tour);

    // Try a few more starts
    {
        vector<int> starts;
        if(N<=5000) for(int i=1;i<min(N,10);i++) starts.push_back(i);
        else starts.push_back(N/2);
        for(int s : starts){
            if(elapsed()>0.2) break;
            auto t2 = buildNNTour(s);
            double c2 = tourCost(t2);
            if(c2 < curCost){curCost=c2; tour=t2;}
        }
    }

    // 2-opt with penalty awareness
    // For speed: compute step cost inline
    auto stepCost = [&](int step, int from, int to) -> double {
        return ddist(from,to) * getmult(step, from);
    };

    // Penalty-aware 2-opt
    // Reversing tour[i..j] changes steps i to j+1
    // We need to recompute cost for those steps

    int twoOptWindow = min(N-1, 200);

    bool globalImproved = true;
    while(globalImproved && elapsed()<1.7){
        globalImproved = false;

        // 2-opt
        for(int i=1;i<N-1 && elapsed()<1.6;i++){
            int jmax = min(i+twoOptWindow, N-1);
            for(int j=i+1;j<=jmax;j++){
                // Compute old cost for steps i..j+1 (edges i to j+1 if j+1<=N)
                int hiStep = min(j+1, N);
                double oldC=0;
                for(int s=i;s<=hiStep;s++) oldC+=stepCost(s, tour[s-1], tour[s]);

                // Reverse tour[i..j]
                reverse(tour.begin()+i, tour.begin()+j+1);

                double newC=0;
                for(int s=i;s<=hiStep;s++) newC+=stepCost(s, tour[s-1], tour[s]);

                if(newC < oldC - 1e-10){
                    curCost += newC - oldC;
                    globalImproved = true;
                } else {
                    reverse(tour.begin()+i, tour.begin()+j+1);
                }
            }
        }

        // Or-opt: relocate single cities
        for(int i=1;i<N && elapsed()<1.7;i++){
            int city = tour[i];
            // Cost of current position: edges at step i and i+1
            // Try moving city to other positions nearby

            double bestDelta = -1e-10;
            int bestJ = -1;

            int lo = max(1, i-100), hi = min(N-1, i+100);
            for(int j=lo;j<=hi;j++){
                if(j==i || j==i-1) continue;

                // Compute affected range
                int rlo = min(i,j), rhi = max(i,j)+1;
                rhi = min(rhi, N);

                double oldC=0;
                for(int s=rlo;s<=rhi;s++) oldC+=stepCost(s, tour[s-1], tour[s]);

                // Simulate move
                vector<int> seg;
                for(int k=rlo-1;k<=rhi;k++){
                    if(k<0||k>N) continue;
                    if(k==i) continue;
                    if(j>i){
                        seg.push_back(tour[k]);
                        if(k==j) seg.push_back(city);
                    } else {
                        if(k==j-1){
                            seg.push_back(tour[k]);
                            seg.push_back(city);
                        } else {
                            seg.push_back(tour[k]);
                        }
                    }
                }

                double newC=0;
                for(int k=1;k<(int)seg.size();k++){
                    int step = rlo + k - 1;
                    if(step>=1&&step<=N)
                        newC += stepCost(step, seg[k-1], seg[k]);
                }

                double delta = newC - oldC;
                if(delta < bestDelta){
                    bestDelta = delta;
                    bestJ = j;
                }
            }

            if(bestJ != -1){
                int j = bestJ;
                int city2 = tour[i];
                if(j > i){
                    for(int k=i;k<j;k++) tour[k]=tour[k+1];
                    tour[j]=city2;
                } else {
                    for(int k=i;k>j;k--) tour[k]=tour[k-1];
                    tour[j]=city2;
                }
                curCost += bestDelta;
                globalImproved = true;
            }
        }
    }

    cout << N+1 << "\n";
    for(int i=0;i<=N;i++) cout << tour[i] << "\n";
}
